DO $$
DECLARE m DATE := '2026-01-01';
BEGIN
    WHILE m < '2028-01-01' LOOP
        EXECUTE format(
            'CREATE TABLE ${schema_name}.%I PARTITION OF ${schema_name}.POSITION FOR VALUES FROM (%L) TO (%L)',
            'POSITION_' || to_char(m, 'YYYYMM'), m, m + INTERVAL '1 month'
        );
        m := m + INTERVAL '1 month';
    END LOOP;
END;
$$

